#!/usr/bin/env python3
from pathlib import Path
import shutil
import sys

FS = ';; Familiar direct-style filesystem API layered over promise-based std.native.File effects.\n(ns std.fs\n  (:config {:override [list]})\n  (:require [std.foundation.string :as str]\n            [std.fs.path :as path]\n            [std.fs.walk :as walk]))\n\n(def copy-default-options\n  {:replace? false\n   :parents? false\n   :preserve-modified? false})\n\n(def delete-default-options\n  {:recursive? false\n   :missing-ok? false})\n\n(defn stat\n  "Returns no-follow metadata for a canonical logical path."\n  [value]\n  (deref (File/stat (path/normalise value))))\n\n(defn exists?\n  "Returns true when a logical path exists and false only for not-found."\n  [value]\n  (deref (File/exists? (path/normalise value))))\n\n(defn entries\n  "Returns sorted immediate no-follow entry metadata."\n  [value]\n  (deref (File/entries (path/normalise value))))\n\n(defn list\n  "Returns sorted immediate canonical path strings."\n  [value]\n  (deref (File/list (path/normalise value))))\n\n(defn read-bytes\n  "Reads a regular file and returns its bytes directly."\n  [value]\n  (deref (File/read (path/normalise value))))\n\n(defn write-bytes\n  "Writes bytes and returns the canonical logical path."\n  ([value bytes]\n   (write-bytes value bytes {}))\n  ([value bytes options]\n   (deref (File/write (path/normalise value) bytes options))))\n\n(defn file?\n  "Returns true when value names a regular file."\n  [value]\n  (= (:type (stat value)) :file))\n\n(defn directory?\n  "Returns true when value names a directory."\n  [value]\n  (= (:type (stat value)) :directory))\n\n(defn symlink?\n  "Returns true when value names a symbolic link."\n  [value]\n  (= (:type (stat value)) :symlink))\n\n(defn select\n  "Returns deterministic traversal entries accepted by predicate."\n  ([value predicate]\n   (select value predicate {}))\n  ([value predicate options]\n   (vec (filter predicate (walk/walk value options)))))\n\n(defn create-directory\n  "Creates a directory and returns its canonical logical path."\n  ([value]\n   (create-directory value {}))\n  ([value options]\n   (deref (File/mkdir (path/normalise value) options))))\n\n(def mkdir create-directory)\n\n(defn temp-file\n  "Atomically creates a temporary file beneath parent."\n  ([parent]\n   (temp-file parent {}))\n  ([parent options]\n   (deref (File/temp-file (path/normalise parent) options))))\n\n(defn temp-directory\n  "Atomically creates a temporary directory beneath parent."\n  ([parent]\n   (temp-directory parent {}))\n  ([parent options]\n   (deref (File/temp-directory (path/normalise parent) options))))\n\n(defn copy-single\n  "Copies one regular file and returns the canonical target path."\n  ([source target]\n   (copy-single source target {}))\n  ([source target options]\n   (deref\n    (File/copy (path/normalise source)\n               (path/normalise target)\n               options))))\n\n(defn move\n  "Moves one file or directory and returns the canonical target path."\n  ([source target]\n   (move source target {}))\n  ([source target options]\n   (deref\n    (File/move (path/normalise source)\n               (path/normalise target)\n               options))))\n\n(defn- map-merge\n  [left right]\n  (reduce (fn [output entry]\n            (assoc output (nth entry 0) (nth entry 1)))\n          left\n          right))\n\n(defn- copy-invalid-target?\n  [source target]\n  (or (= source target)\n      (= source "/")\n      (str/starts-with? target (str source "/"))))\n\n(defn- delete-tree\n  [value options]\n  (letfn [(delete-many [children]\n            (loop [index 0\n                   deleted []]\n              (if (= index (count children))\n                deleted\n                (let [child (nth children index)\n                      values (delete-node (:path child))]\n                  (recur (inc index)\n                         (reduce conj deleted values))))))\n          (delete-node [current]\n            (let [entry (stat current)]\n              (if (and (:recursive? options)\n                       (= (:type entry) :directory))\n                (let [deleted (delete-many (entries current))\n                      deleted-path\n                      (deref (File/delete current {:missing-ok? false}))]\n                  (conj deleted deleted-path))\n                [(deref (File/delete current {:missing-ok? false}))])))]\n    (delete-node value)))\n\n(defn delete\n  "Deletes a file, symlink, or empty directory. A simple deletion returns the\n   canonical path. With :recursive? true, directories are deleted in\n   post-order and the deleted canonical paths are returned."\n  ([value]\n   (delete value {}))\n  ([value options]\n   (let [value (path/normalise value)\n         options (merge delete-default-options options)]\n     (if (= value "/")\n       (throw\n        (ex-info "The mounted filesystem root cannot be deleted"\n                 {:error/code :file/denied\n                  :file/operation :delete\n                  :file/path value\n                  :file/target nil}))\n       (if (:recursive? options)\n         (if (exists? value)\n           (delete-tree value options)\n           (if (:missing-ok? options)\n             []\n             [(deref (File/delete value {:missing-ok? false}))]))\n         (deref\n          (File/delete value {:missing-ok? (:missing-ok? options)})))))))\n\n(defn- prepare-directory-target\n  [target options]\n  (if (exists? target)\n    (if (:replace? options)\n      (let [_ (delete target {:recursive? true :missing-ok? false})]\n        (create-directory target\n                          {:parents? (:parents? options)\n                           :exists-ok? false}))\n      (throw\n       (ex-info "Copy target already exists"\n                {:error/code :file/already-exists\n                 :file/operation :copy\n                 :file/path target\n                 :file/target target})))\n    (create-directory target\n                      {:parents? (:parents? options)\n                       :exists-ok? false})))\n\n(defn- copy-tree\n  [source target options]\n  (letfn [(copy-many [children destination-root]\n            (loop [index 0\n                   output {}]\n              (if (= index (count children))\n                output\n                (let [entry (nth children index)\n                      destination (path/join destination-root (:name entry))\n                      values (copy-node (:path entry) destination)]\n                  (recur (inc index)\n                         (map-merge output values))))))\n          (copy-node [current-source current-target]\n            (let [entry (stat current-source)]\n              (cond\n                (= (:type entry) :file)\n                {current-source\n                 (copy-single current-source current-target options)}\n\n                (= (:type entry) :directory)\n                (let [_ (prepare-directory-target current-target options)\n                      children (entries current-source)\n                      values (copy-many children current-target)]\n                  (assoc values current-source current-target))\n\n                :else\n                (throw\n                 (ex-info "Only regular files and directories can be copied"\n                          {:error/code :file/unsupported\n                           :file/operation :copy\n                           :file/path current-source\n                           :file/target current-target})))))]\n    (copy-node source target)))\n\n(defn copy\n  "Copies a regular file or directory tree without following symbolic links.\n   Returns a source-to-target map."\n  ([source target]\n   (copy source target {}))\n  ([source target options]\n   (let [source (path/normalise source)\n         target (path/normalise target)\n         options (merge copy-default-options options)]\n     (if (copy-invalid-target? source target)\n       (throw\n        (ex-info "Copy target must not be the source or one of its descendants"\n                 {:error/code :file/invalid-path\n                  :file/operation :copy\n                  :file/path source\n                  :file/target target}))\n       (copy-tree source target options)))))\n\n(defn copy-into\n  "Copies source beneath directory using the source filename."\n  ([source directory]\n   (copy-into source directory {}))\n  ([source directory options]\n   (let [source (path/normalise source)\n         directory (path/normalise directory)\n         name (path/file-name source)]\n     (if (nil? name)\n       (throw\n        (ex-info "The mounted root has no filename for copy-into"\n                 {:error/code :file/invalid-path\n                  :file/operation :copy\n                  :file/path source\n                  :file/target directory}))\n       (copy source (path/join directory name) options)))))\n'
WALK = ';; Direct-style deterministic traversal over promise-based std.native.File/entries.\n(ns std.fs.walk\n  (:config {:override [walk]})\n  (:require [std.fs.path :as path]))\n\n(def default-options\n  {:include-root? false\n   :max-depth nil\n   :include nil\n   :exclude nil})\n\n(defn- append-values\n  [left right]\n  (reduce conj left right))\n\n(defn- accepted?\n  [entry options]\n  (let [include (:include options)\n        exclude (:exclude options)]\n    (and (or (nil? include) (include entry))\n         (or (nil? exclude) (not (exclude entry))))))\n\n(defn- excluded?\n  [entry options]\n  (let [exclude (:exclude options)]\n    (and (not (nil? exclude)) (exclude entry))))\n\n(defn walk\n  "Returns entry maps in canonical lexical path order.\n\n   Options are :include-root?, :max-depth, :include, and :exclude. Excluded\n   directories are pruned and symbolic links are never followed. Pending\n   provider effects suspend and resume an HTA fiber at the internal deref."\n  ([root]\n   (walk root {}))\n  ([root options]\n   (let [root (path/normalise root)\n         options (merge default-options options)]\n     (letfn [(visit-many [entries depth]\n               (loop [index 0\n                      output []]\n                 (if (= index (count entries))\n                   output\n                   (let [entry (nth entries index)\n                         values (visit-entry entry depth)]\n                     (recur (inc index)\n                            (append-values output values))))))\n             (visit-entry [entry depth]\n               (let [include-entry (accepted? entry options)\n                     max-depth (:max-depth options)\n                     descend (and (= (:type entry) :directory)\n                                  (not (excluded? entry options))\n                                  (or (nil? max-depth) (< depth max-depth)))]\n                 (if descend\n                   (let [children (deref (File/entries (:path entry)))\n                         descendants (visit-many children (inc depth))]\n                     (if include-entry\n                       (conj descendants entry)\n                       descendants))\n                   (if include-entry [entry] []))))]\n       (let [entry (deref (File/stat root))\n             values (visit-entry entry 0)\n             ordered (vec (sort-by :path values))]\n         (if (:include-root? options)\n           ordered\n           (vec (filter (fn [value]\n                          (not (= (:path value) root)))\n                        ordered))))))))\n'
FACADE_TEST = '(ns std.fs.facade-test\n  (:use code.test)\n  (:require [std.foundation.string :as str]\n            [std.fs :as fs]\n            [std.fs.path :as path]\n            [std.fs.walk :as walk]))\n\n(def test-root\n  (fs/temp-directory "/" {:prefix "std-fs-sync-"}))\n\n(def source-root (path/join test-root "source"))\n(def nested-root (path/join source-root "nested"))\n(def alpha-path (path/join source-root "alpha.txt"))\n(def beta-path (path/join source-root "beta.txt"))\n(def gamma-path (path/join nested-root "gamma.txt"))\n(def copy-root (path/join test-root "copy"))\n(def moved-path (path/join test-root "moved.txt"))\n(def single-path (path/join test-root "single.txt"))\n(def into-root (path/join test-root "into"))\n\n(defn- caught-data\n  [f]\n  (try\n    (f)\n    nil\n    (catch Throwable error\n      (ex-data error))))\n\n(def results\n  [(fact "low-level File effects remain promise-based"\n     [(promise? (File/stat test-root))\n      (promise? (File/exists? test-root))\n      (promise? (File/entries test-root))\n      (promise? (File/read (path/join test-root "missing")))\n      (promise? (File/copy (path/join test-root "missing-source")\n                           (path/join test-root "missing-target")))\n      (promise? (File/move (path/join test-root "missing-source")\n                           (path/join test-root "missing-target")))]\n     => [true true true true true true])\n\n   (fact "std.fs returns direct byte metadata predicate and mutation values"\n     (let [directory (fs/create-directory nested-root {:parents? true})\n           alpha (fs/write-bytes alpha-path (str/encode-utf8 "alpha"))\n           beta (fs/write-bytes beta-path (str/encode-utf8 "beta"))\n           gamma (fs/write-bytes gamma-path (str/encode-utf8 "gamma"))\n           bytes (fs/read-bytes alpha-path)\n           entry (fs/stat alpha-path)]\n       [(promise? directory)\n        (promise? alpha)\n        (promise? bytes)\n        (= directory nested-root)\n        (= alpha alpha-path)\n        (= beta beta-path)\n        (= gamma gamma-path)\n        (= (str/decode-utf8 bytes) "alpha")\n        (= (:path entry) alpha-path)\n        (= (:name entry) "alpha.txt")\n        (= (:type entry) :file)\n        (= (:size entry) 5)\n        (map? (:extensions entry))\n        (fs/exists? alpha-path)\n        (fs/file? alpha-path)\n        (fs/directory? nested-root)\n        (fs/symlink? alpha-path)])\n     => [false false false\n         true true true true true\n         true true true true true\n         true true true false])\n\n   (fact "already-resolved std.fs values are not dereferenceable promises"\n     (try\n       (deref (fs/read-bytes alpha-path))\n       false\n       (catch Throwable error\n         true))\n     => true)\n\n   (fact "listing walking selection depth and pruning are deterministic"\n     (let [listed (fs/list source-root)\n           walked (vec (map :path (walk/walk source-root)))\n           selected (vec (map :path\n                              (fs/select source-root\n                                         (fn [entry]\n                                           (= (:type entry) :file)))))\n           included (vec (map :path\n                              (walk/walk\n                               source-root\n                               {:include\n                                (fn [entry]\n                                  (= (:type entry) :file))})))\n           shallow (vec (map :path\n                             (walk/walk source-root {:max-depth 1})))\n           pruned (vec (map :path\n                            (walk/walk\n                             source-root\n                             {:exclude\n                              (fn [entry]\n                                (= (:name entry) "nested"))})))\n           root-only\n           (vec (map :path\n                     (walk/walk source-root\n                                {:include-root? true\n                                 :max-depth 0})))]\n       [(= listed [alpha-path beta-path nested-root])\n        (= walked [alpha-path beta-path nested-root gamma-path])\n        (= selected [alpha-path beta-path gamma-path])\n        (= included [alpha-path beta-path gamma-path])\n        (= shallow [alpha-path beta-path nested-root])\n        (= pruned [alpha-path beta-path])\n        (= root-only [source-root])\n        (promise? listed)\n        (promise? walked)\n        (promise? selected)])\n     => [true true true true true true true false false false])\n\n   (fact "copy copy-into copy-single and move preserve direct result contracts"\n     (let [mapping (fs/copy source-root copy-root)\n           copied-alpha (path/join copy-root "alpha.txt")\n           copied-beta (path/join copy-root "beta.txt")\n           copied-nested (path/join copy-root "nested")\n           copied-gamma (path/join copied-nested "gamma.txt")\n           single (fs/copy-single alpha-path single-path)\n           _ (fs/create-directory into-root)\n           into-target (path/join into-root "alpha.txt")\n           into-mapping (fs/copy-into alpha-path into-root)\n           moved (fs/move single-path moved-path)]\n       [(promise? mapping)\n        (= (count mapping) 5)\n        (= (get mapping source-root) copy-root)\n        (= (get mapping alpha-path) copied-alpha)\n        (= (get mapping beta-path) copied-beta)\n        (= (get mapping nested-root) copied-nested)\n        (= (get mapping gamma-path) copied-gamma)\n        (= (str/decode-utf8 (fs/read-bytes copied-gamma)) "gamma")\n        (= single single-path)\n        (= (get into-mapping alpha-path) into-target)\n        (= (str/decode-utf8 (fs/read-bytes into-target)) "alpha")\n        (= moved moved-path)\n        (not (fs/exists? single-path))\n        (= (str/decode-utf8 (fs/read-bytes moved-path)) "alpha")])\n     => [false true true true true true true true\n         true true true true true true])\n\n   (fact "invalid copy and delete operations throw structured errors directly"\n     (let [descendant (path/join source-root "descendant")\n           copy-error\n           (caught-data\n            (fn []\n              (fs/copy source-root descendant)))\n           delete-error\n           (caught-data\n            (fn []\n              (fs/delete source-root)))\n           copy-into-error\n           (caught-data\n            (fn []\n              (fs/copy-into "/" test-root)))]\n       [[(:error/code copy-error)\n         (:file/operation copy-error)\n         (:file/path copy-error)\n         (:file/target copy-error)]\n        [(:error/code delete-error)\n         (:file/operation delete-error)\n         (:file/path delete-error)\n         (:file/target delete-error)]\n        [(:error/code copy-into-error)\n         (:file/operation copy-into-error)\n         (:file/path copy-into-error)\n         (:file/target copy-into-error)]])\n     => [[:file/invalid-path :copy source-root\n          (path/join source-root "descendant")]\n         [:file/directory-not-empty :delete source-root nil]\n         [:file/invalid-path :copy "/" test-root]])\n\n   (fact "recursive delete is post-order and simple delete returns a path"\n     (let [copied-alpha (path/join copy-root "alpha.txt")\n           copied-beta (path/join copy-root "beta.txt")\n           copied-nested (path/join copy-root "nested")\n           copied-gamma (path/join copied-nested "gamma.txt")\n           deleted (fs/delete copy-root {:recursive? true})\n           simple (fs/delete moved-path)]\n       [(= deleted\n           [copied-alpha\n            copied-beta\n            copied-gamma\n            copied-nested\n            copy-root])\n        (= simple moved-path)\n        (promise? deleted)\n        (promise? simple)\n        (not (fs/exists? copy-root))\n        (not (fs/exists? moved-path))])\n     => [true true false false true true])\n\n   (fact "portable-copy-and-delete-defaults-are-safe"\n     [fs/copy-default-options fs/delete-default-options]\n     => [{:replace? false\n          :parents? false\n          :preserve-modified? false}\n         {:recursive? false\n          :missing-ok? false}])\n\n   (fact "walk-defaults-are-deterministic-and-bounded-only-on-request"\n     walk/default-options\n     => {:include-root? false\n         :max-depth nil\n         :include nil\n         :exclude nil})\n\n   (fact "portable-filesystem-contract-symbols-are-resolvable"\n     (every? (fn [symbol]\n               (not (nil? (resolve symbol))))\n             \'[std.fs/copy\n               std.fs/copy-default-options\n               std.fs/copy-into\n               std.fs/copy-single\n               std.fs/create-directory\n               std.fs/delete\n               std.fs/delete-default-options\n               std.fs/directory?\n               std.fs/entries\n               std.fs/exists?\n               std.fs/file?\n               std.fs/list\n               std.fs/mkdir\n               std.fs/move\n               std.fs/read-bytes\n               std.fs/select\n               std.fs/stat\n               std.fs/symlink?\n               std.fs/temp-directory\n               std.fs/temp-file\n               std.fs/write-bytes])\n     => true)\n\n   (fact "portable-walk-contract-symbols-are-resolvable"\n     (every? (fn [symbol]\n               (not (nil? (resolve symbol))))\n             \'[std.fs.walk/default-options\n               std.fs.walk/walk])\n     => true)\n\n   (fact "temporary test tree is cleaned up"\n     (do\n       (fs/delete test-root {:recursive? true :missing-ok? true})\n       (fs/exists? test-root))\n     => false)])\n\n(pr-str (run \'[std.fs.facade-test]))\n'
JAVA_TEST = 'package hara.truffle;\n\nimport static org.junit.Assert.assertEquals;\nimport static org.junit.Assert.assertFalse;\nimport static org.junit.Assert.assertTrue;\n\nimport java.io.IOException;\nimport java.nio.file.Files;\nimport java.nio.file.LinkOption;\nimport java.nio.file.Path;\nimport org.graalvm.polyglot.Context;\nimport org.graalvm.polyglot.io.IOAccess;\nimport org.junit.Test;\n\npublic class StdFsTest {\n  @Test\n  public void nativeEffectsReturnPromisesAndStructuredCapabilityFailures() {\n    try (Context context = Context.newBuilder(HaraLanguage.ID).build()) {\n      assertTrue(context.eval(HaraLanguage.ID, "(promise? (File/read \\\"/missing\\\"))").asBoolean());\n      assertEquals(\n          ":file/denied",\n          context\n              .eval(\n                  HaraLanguage.ID,\n                  "(try (deref (File/read \\\"/missing\\\"))"\n                      + "     :unexpected"\n                      + "     (catch Throwable error"\n                      + "       (get (ex-data error) :error/code)))")\n              .toString());\n    }\n  }\n\n  @Test\n  public void portableFsIsDirectStyleAndSupportsRecursiveOperations() throws Exception {\n    Path root = Files.createTempDirectory("hara-std-fs-");\n    try (Context context = newContext(root)) {\n      assertEquals(\n          "[\\\"/alpha.bin\\\" \\\"/alpha.bin\\\" \\\"alpha.bin\\\" :file 2 true false]",\n          context\n              .eval(\n                  HaraLanguage.ID,\n                  "(do (require \'std.fs)"\n                      + "    (let [written (std.fs/write-bytes \\\"/alpha.bin\\\" (bytes 1 2))"\n                      + "          entry (std.fs/stat \\\"/alpha.bin\\\")]"\n                      + "      [written (:path entry) (:name entry) (:type entry)"\n                      + "       (:size entry) (map? (:extensions entry))"\n                      + "       (promise? written)]))")\n              .toString());\n\n      assertEquals(\n          ":file/already-exists",\n          context\n              .eval(\n                  HaraLanguage.ID,\n                  "(try (std.fs/write-bytes \\\"/alpha.bin\\\" (bytes 9))"\n                      + "     :unexpected"\n                      + "     (catch Throwable error"\n                      + "       (get (ex-data error) :error/code)))")\n              .toString());\n\n      assertEquals(\n          "/simple-delete",\n          context\n              .eval(\n                  HaraLanguage.ID,\n                  "(do (std.fs/write-bytes \\\"/simple-delete\\\" (bytes 1))"\n                      + "    (std.fs/delete \\\"/simple-delete\\\"))")\n              .toString());\n\n      assertEquals(\n          "[\\\"/native-missing-ok\\\" true true]",\n          context\n              .eval(\n                  HaraLanguage.ID,\n                  "(do (require \'std.fs)"\n                      + "    [(deref (File/delete \\\"/native-missing-ok\\\""\n                      + "                         {:missing-ok? true}))"\n                      + "     (:missing-ok?"\n                      + "      (merge std.fs/delete-default-options"\n                      + "             {:missing-ok? true}))"\n                      + "     (:missing-ok? {:missing-ok? true})])")\n              .toString());\n\n      assertEquals(\n          "/missing-ok",\n          context\n              .eval(\n                  HaraLanguage.ID,\n                  "(std.fs/delete \\\"/missing-ok\\\" {:missing-ok? true})")\n              .toString());\n\n      assertEquals(\n          "[\\\"one\\\" \\\"two\\\" false false]",\n          context\n              .eval(\n                  HaraLanguage.ID,\n                  "(do (std.fs/create-directory \\\"/src/sub\\\" {:parents? true})"\n                      + "    (std.fs/write-bytes \\\"/src/one\\\""\n                      + "                        (std.foundation.string/encode-utf8 \\\"one\\\"))"\n                      + "    (std.fs/write-bytes \\\"/src/sub/two\\\""\n                      + "                        (std.foundation.string/encode-utf8 \\\"two\\\"))"\n                      + "    (let [mapping (std.fs/copy \\\"/src\\\" \\\"/dst\\\")"\n                      + "          bytes (std.fs/read-bytes \\\"/dst/one\\\")]"\n                      + "      [(std.foundation.string/decode-utf8 bytes)"\n                      + "       (std.foundation.string/decode-utf8"\n                      + "        (std.fs/read-bytes \\\"/dst/sub/two\\\"))"\n                      + "       (promise? mapping)"\n                      + "       (promise? bytes)]))")\n              .toString());\n\n      assertEquals(\n          "[\\\"/src/one\\\" \\\"/src/sub/two\\\" \\\"/src/sub\\\" \\\"/src\\\"]",\n          context\n              .eval(\n                  HaraLanguage.ID,\n                  "(std.fs/delete \\\"/src\\\" {:recursive? true})")\n              .toString());\n      assertFalse(\n          context\n              .eval(HaraLanguage.ID, "(std.fs/exists? \\\"/src\\\")")\n              .asBoolean());\n    } finally {\n      deleteTree(root);\n    }\n  }\n\n  @Test\n  public void entriesAreSortedAndTraversalDoesNotFollowSymlinks() throws Exception {\n    Path root = Files.createTempDirectory("hara-std-fs-walk-");\n    Path outside = Files.createTempDirectory("hara-std-fs-outside-");\n    try {\n      Files.writeString(outside.resolve("secret"), "secret");\n      try {\n        Files.createSymbolicLink(root.resolve("link"), outside);\n      } catch (UnsupportedOperationException | IOException | SecurityException ignored) {\n        // The ordering assertions remain valid on filesystems without symlink support.\n      }\n      try (Context context = newContext(root)) {\n        assertEquals(\n            "[\\\"/a\\\" \\\"/b\\\"]",\n            context\n                .eval(\n                    HaraLanguage.ID,\n                    "(do (require \'std.fs)"\n                        + "    (std.fs/write-bytes \\\"/b\\\" (bytes 2))"\n                        + "    (std.fs/write-bytes \\\"/a\\\" (bytes 1))"\n                        + "    (vec (filter (fn [path]"\n                        + "                   (or (= path \\\"/a\\\") (= path \\\"/b\\\")))"\n                        + "                 (std.fs/list \\\"/\\\"))))")\n                .toString());\n        assertEquals(\n            "[\\\"/a\\\" \\\"/b\\\"]",\n            context\n                .eval(\n                    HaraLanguage.ID,\n                    "(vec (map :path"\n                        + "          (filter (fn [entry]"\n                        + "                    (or (= (:path entry) \\\"/a\\\")"\n                        + "                        (= (:path entry) \\\"/b\\\")))"\n                        + "                  (std.fs.walk/walk \\\"/\\\"))))")\n                .toString());\n        if (Files.isSymbolicLink(root.resolve("link"))) {\n          assertEquals(\n              "[[:symlink \\\"/link\\\"]]",\n              context\n                  .eval(\n                      HaraLanguage.ID,\n                      "(vec (map (fn [entry] [(:type entry) (:path entry)])"\n                          + "          (filter (fn [entry] (= (:path entry) \\\"/link\\\"))"\n                          + "                  (std.fs.walk/walk \\\"/\\\"))))")\n                  .toString());\n        }\n      }\n    } finally {\n      deleteTree(root);\n      deleteTree(outside);\n    }\n  }\n\n  private static Context newContext(Path root) {\n    IOAccess io = IOAccess.newBuilder().fileSystem(new HaraMountedFileSystem(root)).build();\n    return Context.newBuilder(HaraLanguage.ID).allowIO(io).build();\n  }\n\n  private static void deleteTree(Path root) throws IOException {\n    if (root == null || !Files.exists(root, LinkOption.NOFOLLOW_LINKS)) return;\n    try (var paths = Files.walk(root)) {\n      for (Path path : paths.sorted(java.util.Comparator.reverseOrder()).toList()) {\n        Files.deleteIfExists(path);\n      }\n    }\n  }\n}\n'
FILESYSTEM_DOC = '# Mounted filesystem APIs\n\nHara exposes a mounted, capability-backed filesystem rather than ambient host filesystem access. The mounted filesystem root is the logical path `/`; it is never the host operating-system root.\n\nThe filesystem surface has three layers:\n\n| Layer | Role |\n| --- | --- |\n| `std.native.File` / `File` | asynchronous promise-based provider boundary and compatibility operations |\n| `std.fs.path` | synchronous, deterministic logical-path algebra |\n| `std.fs` and `std.fs.walk` | synchronous direct-style filesystem operations and traversal over the provider boundary |\n\n## Logical paths\n\nEvery observable filesystem path is a canonical absolute logical path:\n\n```clojure\n(std.fs.path/normalise "src//./main.hal")\n;; => "/src/main.hal"\n```\n\nThe common path contract is:\n\n- `/` is the attached provider root.\n- Relative input is accepted for convenience and resolved from `/`.\n- `/` is the only separator, on every host platform.\n- Duplicate separators and `.` segments are removed.\n- `..` is resolved, but escaping above `/` is rejected.\n- `~`, host working directories, Windows drives, and host-specific separators are not expanded.\n- Host paths are created only inside a provider implementation.\n\n`std.fs.path` provides the pure operations `normalise`, `join`, `resolve`, `parent`, `root`, `file-name`, `segments`, `relativize`, `subpath`, `suffix`, `add-suffix`, `remove-suffix`, and `replace-suffix`.\n\n## Effect and error contract\n\nThe low-level `File` object is promise-based. A valid `File` effect call immediately returns a promise. Capability failures, missing entries, permission failures, and provider I/O failures reject that promise. Arity and argument-type errors remain synchronous.\n\nThe portable `std.fs` and `std.fs.walk` facades are direct-style. They dereference each `File` effect internally and return the final Hara value. A rejected provider promise therefore becomes a thrown Hara error at the facade boundary.\n\nIn an HTA session or evaluation, dereferencing a pending host promise suspends the current fiber and resumes it when the provider completes. Browser-backed IndexedDB operations remain non-blocking: the Hara fiber waits, but the browser thread does not.\n\nBoth levels remain available:\n\n```clojure\n(fs/read-bytes "/data.bin")\n;; => bytes\n\n(deref (File/read "/data.bin"))\n;; => bytes\n```\n\nThe result of `fs/read-bytes` is already a byte value, so `(deref (fs/read-bytes path))` is intentionally invalid.\n\nProvider failures are `ExceptionInfo` values with stable data:\n\n```clojure\n{:error/code     :file/not-found\n :file/operation :read\n :file/path      "/missing"\n :file/target    nil}\n```\n\nPortable code should branch on `:error/code`, not host error text. Stable codes include:\n\n- `:file/not-found`\n- `:file/already-exists`\n- `:file/invalid-path`\n- `:file/outside-root`\n- `:file/not-directory`\n- `:file/is-directory`\n- `:file/directory-not-empty`\n- `:file/permission-denied`\n- `:file/unsupported`\n- `:file/io`\n\n`File/exists?` fulfills with `false` only for not-found. `std.fs/exists?` returns that boolean directly. Other failures reject at `File` and are thrown by `std.fs`.\n\n## Native provider boundary\n\nThe native static object is available as `File` and has the runtime identity `std.native.File`. Its effectful operations are:\n\n```text\nread write exists? stat entries list walk mkdir delete\ncopy move temp-file temp-directory\n```\n\nEvery valid effectful call in this layer returns a promise.\n\nThe native options are:\n\n```clojure\nwrite          {:mode :create|:replace|:append, :parents? false}\nmkdir          {:parents? true, :exists-ok? true}\ndelete         {:missing-ok? false}\ncopy           {:replace? false, :parents? false, :preserve-modified? false}\nmove           {:replace? false, :parents? false, :atomic? false}\ntemp-file      {:prefix "tmp", :suffix ""}\ntemp-directory {:prefix "tmp"}\n```\n\n`stat` and `entries` fulfill with no-follow metadata maps:\n\n```clojure\n{:path        "/dir/item"\n :name        "item"\n :type        :file | :directory | :symlink | :other\n :size        42 | nil\n :modified-at 1780000000000\n :extensions  {}}\n```\n\n`:size` is present only for a regular file. `entries` fulfills with immediate entries sorted by canonical path. `list` remains a sorted path-string projection of `entries`.\n\n`parent`, `join`, `resolve`, `list`, and `walk` remain callable as compatibility operations. New portable code should use `std.fs.path`, `std.fs/entries`, and `std.fs.walk/walk` instead.\n\n## Portable `std.fs`\n\nRequire the portable facade and path algebra explicitly:\n\n```clojure\n(ns example.files\n  (:require [std.fs :as fs]\n            [std.fs.path :as path]\n            [std.fs.walk :as walk]))\n```\n\nThe portable facade provides:\n\n```text\nstat entries list select\nexists? file? directory? symlink?\nread-bytes write-bytes\nmkdir create-directory\ntemp-file temp-directory\ncopy-single copy copy-into move delete\n```\n\nThese functions return direct values:\n\n```clojure\n(fs/create-directory "/build" {:parents? true})\n;; => "/build"\n\n(fs/write-bytes "/build/output.bin" bytes\n                {:mode :create :parents? true})\n;; => "/build/output.bin"\n\n(fs/copy "/src" "/backup/src" {:parents? true})\n;; => {"/src" "/backup/src", ...}\n\n(fs/delete "/backup" {:recursive? true})\n;; => ["/backup/src/..." ... "/backup"]\n```\n\nResult shapes are:\n\n- `stat` returns an entry map.\n- `exists?`, `file?`, `directory?`, and `symlink?` return booleans.\n- `entries`, `list`, `walk`, and `select` return vectors.\n- `read-bytes` returns bytes.\n- Write, directory creation, temporary creation, `copy-single`, and `move` return canonical paths.\n- `copy` and `copy-into` return source-to-target maps.\n- Simple `delete` returns a canonical path; recursive `delete` returns post-order paths.\n\nCopy defaults are non-destructive:\n\n```clojure\n{:replace? false\n :parents? false\n :preserve-modified? false}\n```\n\nDelete defaults are also non-destructive:\n\n```clojure\n{:recursive? false\n :missing-ok? false}\n```\n\nRecursive operations throw on the first failure. Completed provider mutations are not rolled back or returned as partial success.\n\n`copy-into` copies the source beneath a destination directory using the source filename. The mounted root has no filename, so `(fs/copy-into "/" target)` throws `:file/invalid-path` directly.\n\n## Deterministic traversal\n\n`std.fs.walk/walk` traverses `File/entries` in canonical lexical order and returns its final vector directly. It never follows symbolic links.\n\n```clojure\n(walk/walk "/src"\n           {:include-root? false\n            :max-depth 3\n            :include (fn [entry] (= (:type entry) :file))\n            :exclude (fn [entry] (= (:name entry) ".cache"))})\n```\n\nOptions are:\n\n```clojure\n{:include-root? false\n :max-depth nil\n :include nil\n :exclude nil}\n```\n\nAn excluded directory is pruned, not merely omitted from the result. `max-depth` limits descent relative to the requested root.\n\n## Security and portability invariants\n\nProviders must preserve these invariants:\n\n- Logical `..` cannot escape the mounted root.\n- Host absolute paths and drive syntax cannot select ambient host files.\n- Metadata and traversal do not follow links.\n- A link or ancestor link cannot be used to escape the provider root.\n- Recursive copy and delete treat a symbolic link as an entry, never as a directory to traverse.\n- Copying or moving a directory into itself or a descendant is rejected.\n- The mounted root cannot be deleted.\n- Temporary entries are created atomically beneath the explicit logical parent.\n\nThe JVM, Rust-native/WASI, memory, and unsupported providers are expected to expose the same logical results and stable error data even though their host implementations differ.\n'
FOUNDATION_ARCH = '# Current `std.foundation` architecture\n\nThis document describes the implementation boundary represented by Hara\'s registered standard-library inventory. It is intentionally narrower than historical Foundation plans and annex drafts.\n\n## Loadable Foundation namespaces\n\nThe current public Foundation family is:\n\n```text\nstd.foundation\nstd.foundation.bytes\nstd.foundation.coroutine\nstd.foundation.pretty\nstd.foundation.promise\nstd.foundation.string\n```\n\n`core/rust/standard-library.namespaces` is authoritative for loadable standard-library namespace membership. A source file, test fixture, automatic alias, or native object does not become a public namespace merely because it is present in the repository or visible to an evaluator.\n\nThe root `std.foundation` namespace owns the portable value layer: composition, collections, sequence operations, set algebra, metadata, references, macros, structural traversal, and the small language-level helpers automatically referred into ordinary namespaces.\n\nThe five child namespaces provide separately aliased portable/native-backed library surfaces:\n\n| Namespace | Default alias | Role |\n| --- | --- | --- |\n| `std.foundation.string` | `str` | portable string facade |\n| `std.foundation.bytes` | `bytes` | byte values and operations |\n| `std.foundation.promise` | `promise` | promises and protocol facade |\n| `std.foundation.coroutine` | `co` | coroutine facade |\n| `std.foundation.pretty` | `pretty` | document and pretty rendering |\n\n## Native static objects\n\nThe schema-v2 API manifest records native static objects separately from loadable namespaces. The current cross-profile runtime configuration includes objects such as `Edn`, `Json`, `Crypto`, `File`, `Socket`, `Host`, and `Kernel`, backed by `std.native.*` runtime identities. They are available without requiring file-backed `std.native.*` namespaces.\n\nFor example:\n\n```clojure\n(Edn/read "{:a 1}")\n(Json/write {"a" 1})\n(Crypto/sha256 bytes)\n```\n\nThe presence of aliases such as `Edn` or identities such as `std.native.Edn` does **not** imply that `std.foundation.edn` or another retired Foundation child is loadable.\n\n`OS` remains the migration direction for the former `std.foundation.os` API, but availability and export shape are runtime-profile concerns to be proven by cross-runtime conformance. A process handle is a runtime value, not an automatic `Process` static-object alias. Neither should be presented as part of the common native-object inventory without profile evidence.\n\n## Higher-level ownership\n\nFunctionality above the native substrate belongs to focused portable libraries:\n\n- mounted filesystem paths and direct-style, fiber-aware operations under `std.fs.path`, `std.fs.walk`, and `std.fs`; the underlying `File` object remains promise-based; see [Mounted filesystem APIs](filesystem.md);\n- formatting, tables, reports, and terminal presentation under `std.format.*`;\n- component lifecycle under `std.lib.component`;\n- cryptographic algorithms above native primitives under `std.crypto.*`;\n- collection helpers not retained in the root value layer under `std.lib.collection`.\n\nPlanned replacements must be recorded as planned rather than presented as implemented.\n\n## Migration and generated API data\n\n`core/spec/std/foundation-migrations.json` records former names, their status, replacement or disposition, rewrite guidance, and evidence.\n\n`scripts/generate_foundation_api_manifest.py` combines:\n\n1. the registered namespace inventory;\n2. source-derived public binding data;\n3. runtime alias/native-object configuration; and\n4. the migration ledger.\n\nThe resulting schema-v2 manifest records repository-relative provenance, a pinned source commit, and deterministic surface and migration digests. It is the source consumed by the specification registry and generated documentation. Downstream repositories must not maintain independent handwritten Foundation inventories.\n\n## Test placement\n\nOrdinary tests under `core/lib/test/std/foundation/` correspond only to current Foundation child namespaces. Root Foundation behavior lives in `core/lib/test/std/foundation*_test.hal`. Common native static-object behavior is tested without requiring retired `std.foundation.*` children. Profile-specific OS/process behavior, capability-provider behavior, and higher-level portable-library behavior belong under the runtime or library that owns them.\n'

FOUNDATION_OLD = ';; Higher-level ownership:\n;;   * portable path operations: std.fs.path (broader std.fs remains planned)\n;;   * formatting, reports, tables, and terminal rendering: std.format.*'
FOUNDATION_NEW = ';; Higher-level ownership:\n;;   * mounted filesystem paths and direct-style operations: std.fs.path,\n;;     std.fs.walk, and std.fs (File remains the promise-based provider edge)\n;;   * formatting, reports, tables, and terminal rendering: std.format.*'

FILES = {
    "core/lib/src/std/fs.hal": FS,
    "core/lib/src/std/fs/walk.hal": WALK,
    "core/lib/test/std/fs/facade_test.hal": FACADE_TEST,
    "core/java/src/test/java/hara/truffle/StdFsTest.java": JAVA_TEST,
    "core/spec/std/filesystem.md": FILESYSTEM_DOC,
    "core/spec/std/foundation-architecture.md": FOUNDATION_ARCH,
}

def write_candidates(repo: Path, output: Path) -> None:
    if output.exists():
        shutil.rmtree(output)
    for relative, content in FILES.items():
        target = output / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content)
    foundation = (repo / "core/lib/src/std/foundation.hal").read_text()
    if FOUNDATION_OLD not in foundation:
        raise SystemExit("std.foundation ownership header marker not found")
    target = output / "core/lib/src/std/foundation.hal"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(foundation.replace(FOUNDATION_OLD, FOUNDATION_NEW, 1))

def apply_candidates(repo: Path, output: Path, paths: list[str]) -> None:
    for relative in paths:
        source = output / relative
        if not source.is_file():
            raise SystemExit(f"candidate missing: {relative}")
        target = repo / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, target)

def main() -> None:
    if len(sys.argv) < 4:
        raise SystemExit(
            "usage: materialize.py candidates|apply REPO CANDIDATES [PATH ...]"
        )
    mode = sys.argv[1]
    repo = Path(sys.argv[2]).resolve()
    output = Path(sys.argv[3]).resolve()
    if mode == "candidates":
        write_candidates(repo, output)
    elif mode == "apply":
        apply_candidates(repo, output, sys.argv[4:])
    else:
        raise SystemExit(f"unknown mode: {mode}")

if __name__ == "__main__":
    main()
